'use strict';

/* SectionSeparatorOverlay — RF-CR-SECTION-SEPARATOR-1
 *
 * Renders the Crystal-like 1px-dark / 2px-gray / 1px-dark hairline relief
 * at the bottom edge of every Design-mode section, in a dedicated
 * `position: fixed` layer appended to <body> — entirely outside
 * #workspace/#viewport/#canvas-layer's scaled/clipped subtree.
 *
 * Why a screen-space overlay and not a CSS rule on .cr-section itself: a
 * CSS gradient declared inside #viewport (which carries the zoom
 * transform:scale(z)) has to divide its own thickness by --geo-zoom so the
 * POST-transform result stays constant — proven live this survives for a
 * single hairline, but a 4px-total 3-stop gradient sized that way blends
 * away or misrenders at some zoom fractions since the whole thing is
 * painted at a sub-device-pixel size pre-transform. Positioning a fixed
 * element from the section's own POST-transform getBoundingClientRect (the
 * same technique engines/SelectionOverlayPreviewLayers.js's
 * rf-extended-guide-layer already uses for the same class of problem) means
 * the 4px thickness is a REAL, already-final screen measurement — no zoom
 * division needed anywhere in this file.
 *
 * Ruler crossing: Crystal's separator visibly reaches into the interior of
 * the left (vertical) ruler gutter. #ruler-v is a sibling of #workspace,
 * outside this layer's own positioning context, so a small stub is painted
 * directly inside #ruler-v (mirroring
 * SelectionOverlayPreviewLayers.js's _paintRulerGuideStub for the
 * equivalent guide-into-ruler case) rather than trying to extend the fixed
 * line itself across a container it isn't part of.
 */
const SectionSeparatorOverlay = (() => {
  const LAYER_ID = 'rf-section-separator-layer';
  const GRIP_LAYER_ID = 'rf-section-collapse-grip-layer';
  const LINE_CLASS = 'rf-section-sep-line';
  const RULER_STUB_CLASS = 'rf-section-sep-ruler-stub';
  // DESIGNER-CLEAN-SECTION-0PX-MANUAL-FLOOR-01: `section-resize-handle` is
  // the EXACT class engines/EngineCoreRoutingPointerHelpers.js's router
  // already matches via `closest('.section-resize-handle')` to dispatch a
  // pointerdown to SectionResizeEngine.onPointerDown(event,
  // node.dataset.sectionId) -- reusing it here means this grip needs ZERO
  // router changes; it is routed by the exact same, already-correct code
  // path a normal handle uses, just from a differently-positioned element.
  const GRIP_ROUTER_CLASS = 'section-resize-handle';
  const GRIP_CLASS = 'rf-section-collapse-grip';
  const GRIP_W = 22; // matches SectionLabelOverlay.js's own gutter-tab width
  const GRIP_H = 12; // fixed screen px, stable at any zoom (like TOTAL_PX)
  const GRIP_GAP = 2; // breathing room above the previous section's own handle zone

  const DARK_PX = 1;
  const GRAY_PX = 2;
  const TOTAL_PX = DARK_PX * 2 + GRAY_PX; // 4 visual px, stable at any zoom
  const DARK = '#303030';
  const LIGHT = '#d6d6d6';

  function _gradient() {
    return `linear-gradient(to bottom, ${DARK} 0, ${DARK} ${DARK_PX}px, ${LIGHT} ${DARK_PX}px, ${LIGHT} ${DARK_PX + GRAY_PX}px, ${DARK} ${DARK_PX + GRAY_PX}px, ${DARK} ${TOTAL_PX}px)`;
  }

  function _ensureLayer() {
    if (typeof document === 'undefined' || !document.body) return null;
    let layer = document.getElementById(LAYER_ID);
    if (!layer) {
      layer = document.createElement('div');
      layer.id = LAYER_ID;
      layer.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:3;overflow:visible';
      document.body.appendChild(layer);
    }
    return layer;
  }

  // DESIGNER-CLEAN-SECTION-0PX-MANUAL-FLOOR-01: a SEPARATE layer from
  // _ensureLayer()'s (kept minimal-blast-radius -- the existing
  // separator-line layer's own parentage is untouched), appended to
  // #workspace itself rather than document.body. #workspace has
  // `position:relative` and no `transform`, so it does NOT establish a
  // new containing block for `position:fixed` descendants -- coordinates
  // computed the exact same way as the main layer (real, final,
  // viewport-relative getBoundingClientRect values) stay correct. The
  // ONLY reason to anchor here instead of document.body: real DOM
  // descendants of #workspace naturally bubble pointerdown into
  // EngineCoreRoutingWorkspace.js's existing `ws.addEventListener
  // ('pointerdown', ...)` listener -- a document.body-level sibling
  // (like the main separator layer) never does, since DOM event bubbling
  // follows the actual parent chain, not visual z-index stacking.
  // Confirmed live: a grip appended to document.body was correctly
  // identified by real elementFromPoint() probes but its real
  // page.mouse.down() never reached SectionResizeEngine at all (_drag
  // stayed null) for exactly this reason. This keeps the router
  // (engines/EngineCoreRoutingPointerHelpers.js /
  // EngineCoreRoutingWorkspace.js) completely unchanged -- zero new
  // geometry, zero new listeners; the grip is simply routed by the
  // SAME, already-correct `.section-resize-handle` dispatch a normal
  // handle uses.
  function _ensureGripLayer() {
    if (typeof document === 'undefined') return null;
    const host = document.getElementById('workspace') || document.body;
    if (!host) return null;
    let layer = document.getElementById(GRIP_LAYER_ID);
    if (!layer) {
      layer = document.createElement('div');
      layer.id = GRIP_LAYER_ID;
      layer.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:3;overflow:visible';
      host.appendChild(layer);
    }
    return layer;
  }

  function _lineEl(layer, sectionId) {
    const cls = `${LINE_CLASS}-${sectionId}`;
    let el = layer.querySelector(`:scope > .${cls}`);
    if (!el) {
      el = document.createElement('div');
      el.className = `${LINE_CLASS} ${cls}`;
      el.style.position = 'fixed';
      el.style.backgroundRepeat = 'no-repeat';
      layer.appendChild(el);
    }
    return el;
  }

  // DESIGNER-CLEAN-SECTION-0PX-MANUAL-FLOOR-01: a section whose real
  // height is truly 0 has no rendered body left to grab -- its own
  // .section-resize-handle (position:absolute inside the section,
  // straddling ITS OWN bottom edge) becomes screen-position-IDENTICAL to
  // the PREVIOUS section's resize handle, since this section's top and
  // bottom edges now coincide with each other AND with that boundary
  // line. Confirmed live via elementsFromPoint(): a real mouse click
  // there resolves non-deterministically to whichever element the
  // browser's native hit-test happens to pick first (the previous
  // section's handle, a content element, or the NEXT section's body --
  // never reliably THIS section's own handle). A 0px section must still
  // be independently re-expandable, so it needs its OWN, exclusively-
  // owned, real hit target -- one that shares ZERO screen pixels with
  // any other interactive element, not merely a higher z-index (that
  // would just move the ambiguity onto the section ABOVE, which must
  // remain independently resizable too).
  //
  // Reuses the class the router already dispatches on
  // (GRIP_ROUTER_CLASS) so SectionResizeEngine's existing pointerdown/
  // move/up lifecycle handles it completely unchanged -- this file only
  // ever paints the grip and sets its own data-section-id; it never
  // decides heights, never touches DS, never implements resize logic.
  function _gripEl(layer, sectionId) {
    const cls = `${GRIP_CLASS}-${sectionId}`;
    let el = layer.querySelector(`:scope > .${cls}`);
    if (!el) {
      el = document.createElement('div');
      el.className = `${GRIP_ROUTER_CLASS} ${GRIP_CLASS} ${cls}`;
      el.dataset.sectionId = sectionId;
      el.style.position = 'fixed';
      el.style.pointerEvents = 'auto';
      el.style.cursor = 'ns-resize';
      el.style.boxSizing = 'border-box';
      el.style.border = '1px solid rgba(0,0,0,.35)';
      el.style.borderBottom = 'none';
      layer.appendChild(el);
    }
    return el;
  }

  function _removeGrip(layer, sectionId) {
    const el = layer.querySelector(`:scope > .${GRIP_CLASS}-${sectionId}`);
    if (el) el.remove();
  }

  // Mirrors SelectionOverlayPreviewLayers.js's _paintRulerGuideStub (the
  // "h axis" branch — a horizontal line's left endpoint crossing into the
  // vertical ruler), adapted to paint the 3-band gradient instead of a
  // single color.
  function _paintRulerStub(sectionId, sectionRect) {
    const rulerV = document.getElementById('ruler-v');
    if (!rulerV) return;
    rulerV.style.position = rulerV.style.position || 'relative';
    const cls = `${RULER_STUB_CLASS}-${sectionId}`;
    let stub = rulerV.querySelector(`:scope > .${cls}`);
    if (!stub) {
      stub = document.createElement('div');
      stub.className = `${RULER_STUB_CLASS} ${cls}`;
      stub.style.position = 'absolute';
      stub.style.pointerEvents = 'none';
      stub.style.zIndex = '6';
      stub.style.left = '0px';
      stub.style.width = '100%';
      stub.style.backgroundRepeat = 'no-repeat';
      rulerV.appendChild(stub);
    }
    const hostRect = rulerV.getBoundingClientRect();
    stub.style.top = `${sectionRect.bottom - hostRect.top - TOTAL_PX / 2}px`;
    stub.style.height = `${TOTAL_PX}px`;
    stub.style.backgroundImage = _gradient();
  }

  // CLEAN-SECTIONS-OVERLAY-WORKSPACE-CLIP-01: this layer is `position:
  // fixed` on <body> specifically to escape .cr-section's own
  // contain:layout paint (see file header) -- but that also lets it escape
  // #workspace's OWN visible viewport. At high zoom, when the zoomed
  // canvas is wider than #workspace's own box, an unclipped rect.left/
  // rect.width paints the hairline straight over the right-side panels
  // (Explorador de campos, properties) that live OUTSIDE #workspace, not
  // over document.body/window bounds. Clip explicitly against
  // #workspace.getBoundingClientRect() (never document.body, never
  // window.innerWidth -- those don't know where the side panels are).
  function _clipToWorkspace(rect) {
    const ws = document.getElementById('workspace');
    if (!ws) return { left: rect.left, width: rect.width, visible: rect.width > 0, wsRect: null };
    const wsRect = ws.getBoundingClientRect();
    const visibleLeft = Math.max(rect.left, wsRect.left);
    const visibleRight = Math.min(rect.right, wsRect.right);
    const visibleWidth = Math.max(0, visibleRight - visibleLeft);
    return { left: visibleLeft, width: visibleWidth, visible: visibleWidth > 0, wsRect };
  }

  function render() {
    if (typeof document === 'undefined' || typeof DS === 'undefined' || !Array.isArray(DS.sections)) return;
    if (DS.previewMode) { clear(); return; }
    const layer = _ensureLayer();
    if (!layer) return;
    const gripLayer = _ensureGripLayer();
    const gradient = _gradient();
    const zoom = (typeof DS.zoom === 'number' && DS.zoom > 0) ? DS.zoom : 1;
    const seen = new Set();
    const seenGrips = new Set();
    DS.sections.forEach((sec) => {
      if (sec.visible === false) { if (gripLayer) _removeGrip(gripLayer, sec.id); return; }
      const div = document.querySelector(`.cr-section[data-section-id="${sec.id}"]`);
      if (!div) { if (gripLayer) _removeGrip(gripLayer, sec.id); return; }
      const rect = div.getBoundingClientRect();
      if (!rect.width || !rect.height) {
        // Truly 0px: no separator to paint (nothing to draw a hairline
        // into), but this section still needs its own exclusive resize
        // affordance -- see _gripEl's header comment.
        if (rect.width && gripLayer) {
          seenGrips.add(sec.id);
          const grip = _gripEl(gripLayer, sec.id);
          const clip = _clipToWorkspace(rect);
          if (!clip.visible) {
            grip.style.display = 'none';
          } else {
            const boundary = rect.bottom; // === rect.top here (0px height)
            const prevHandleZoneTop = boundary - (3 * zoom);
            grip.style.display = '';
            // Left-anchored, not right-anchored: the right edge of
            // #workspace is where a vertical scrollbar track lives
            // (.rf-scrollbar-track--v, z-index:150) whenever content
            // overflows -- confirmed live it swallows a right-anchored
            // grip almost entirely. The section's own LEFT edge is the
            // same zone every real-mouse resize-handle drag in this
            // entire phase has already used successfully (box.x+60), and
            // is never covered by that scrollbar.
            grip.style.left = `${clip.left}px`;
            grip.style.width = `${Math.min(GRIP_W, clip.width)}px`;
            grip.style.top = `${prevHandleZoneTop - GRIP_GAP - GRIP_H}px`;
            grip.style.height = `${GRIP_H}px`;
            grip.style.background = getComputedStyle(div).backgroundColor || '#4a90d9';
            grip.style.zIndex = '11';
            grip.title = `${sec.label || sec.id} (0px, arrastrar para expandir)`;
          }
        }
        return;
      }
      seen.add(sec.id);
      const el = _lineEl(layer, sec.id);
      const clip = _clipToWorkspace(rect);
      const lineTop = rect.bottom - TOTAL_PX / 2;
      const lineBottom = lineTop + TOTAL_PX;
      const verticallyVisible = clip.wsRect ? (lineBottom > clip.wsRect.top && lineTop < clip.wsRect.bottom) : true;
      if (!clip.visible || !verticallyVisible) {
        el.style.display = 'none';
        return;
      }
      el.style.display = '';
      el.style.left = `${clip.left}px`;
      el.style.width = `${clip.width}px`;
      el.style.top = `${lineTop}px`;
      el.style.height = `${TOTAL_PX}px`;
      el.style.backgroundImage = gradient;
      _paintRulerStub(sec.id, rect);
    });
    layer.querySelectorAll(`.${LINE_CLASS}`).forEach((el) => {
      const id = el.className.split(' ').find((c) => c.startsWith(`${LINE_CLASS}-`))?.slice(LINE_CLASS.length + 1);
      if (id && !seen.has(id)) el.remove();
    });
    if (gripLayer) {
      gripLayer.querySelectorAll(`.${GRIP_CLASS}`).forEach((el) => {
        const id = el.className.split(' ').find((c) => c.startsWith(`${GRIP_CLASS}-`))?.slice(GRIP_CLASS.length + 1);
        if (id && !seenGrips.has(id)) el.remove();
      });
    }
    const rulerV = document.getElementById('ruler-v');
    if (rulerV) {
      rulerV.querySelectorAll(`.${RULER_STUB_CLASS}`).forEach((el) => {
        const id = el.className.split(' ').find((c) => c.startsWith(`${RULER_STUB_CLASS}-`))?.slice(RULER_STUB_CLASS.length + 1);
        if (id && !seen.has(id)) el.remove();
      });
    }
  }

  function clear() {
    const layer = typeof document !== 'undefined' ? document.getElementById(LAYER_ID) : null;
    if (layer) layer.innerHTML = '';
    const gripLayer = typeof document !== 'undefined' ? document.getElementById(GRIP_LAYER_ID) : null;
    if (gripLayer) gripLayer.innerHTML = '';
    const rulerV = typeof document !== 'undefined' ? document.getElementById('ruler-v') : null;
    if (rulerV) rulerV.querySelectorAll(`.${RULER_STUB_CLASS}`).forEach((el) => el.remove());
  }

  function init() {
    if (typeof document === 'undefined') return;
    const ws = document.getElementById('workspace');
    if (ws) {
      ws.addEventListener('rf:zoom-changed', render);
    }
    if (typeof ResizeObserver !== 'undefined') {
      const cl = document.getElementById('canvas-layer');
      if (cl) new ResizeObserver(render).observe(cl);
    }
    // PreviewEngineMode.js's show()/hide() are already at their governance
    // byte ceiling, so this can't hook them directly — instead watch the
    // same data-render-mode attribute show() sets synchronously before
    // DS.setPreviewMode(true), catching the Design->Preview transition the
    // instant it happens rather than waiting for some other trigger to
    // eventually call OverlayEngine.render() (hide()'s own render() call
    // already covers the Preview->Design direction).
    if (typeof MutationObserver !== 'undefined' && document.body) {
      new MutationObserver(render).observe(document.body, { attributes: true, attributeFilter: ['data-render-mode'] });
    }
    render();
  }

  // TOTAL_PX exposed read-only for SectionLayoutEngine.js's clean-section
  // collapse floor: that value must stay small enough, IN SCREEN SPACE,
  // that two collapsed sections' hairlines actually touch -- since this
  // hairline is a fixed screen-px thickness (not zoom-scaled, see file
  // header) while a collapsed section's rendered height IS zoom-scaled
  // (raw model px x zoom, via the canvas root's own CSS transform), the
  // model-unit floor has to be derived from THIS constant divided by the
  // current zoom, not a fixed model-px number, or the visual gap reopens
  // at any zoom other than 1.0.
  return { render, clear, init, LAYER_ID, TOTAL_PX };
})();

if (typeof module !== 'undefined') module.exports = SectionSeparatorOverlay;
